import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.DX2KvlNk.js";const k=JSON.parse('{"title":"Development Environment Setup","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/dev-environment.md","filePath":"contributing/dev-environment.md","lastUpdated":1783503169000}'),n={name:"contributing/dev-environment.md"};function o(r,e,l,d,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="development-environment-setup" tabindex="-1">Development Environment Setup <a class="header-anchor" href="#development-environment-setup" aria-label="Permalink to &quot;Development Environment Setup&quot;">​</a></h1><p>For the public contribution contract, use the repository root <a href="https://github.com/atlassian-labs/opensearch-aosc/blob/develop/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a>. It covers issues, pull requests, commit-message conventions, code formatting, and license headers.</p><p>The contributing pages in this documentation are source-tree workflow references. They cover local setup, test selection, package layout, release mechanics, and extension points for people changing AOSC code.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Tool</th><th>Minimum</th><th>Notes</th></tr></thead><tbody><tr><td>JDK (build/Gradle JVM)</td><td>21 for the <code>os3</code> line; 17 for the <code>os2</code> line</td><td>The JVM that runs the build (<code>build_java_version</code> in <code>release/os*.properties</code>). os2 emits Java 11 bytecode (<code>java_version</code>) but its build-tools requires JDK 17; os3 uses 21. Match the Gradle JVM to the line you build.</td></tr><tr><td>Git</td><td>2.x</td><td>Source control.</td></tr><tr><td>Docker</td><td>Recent Docker Desktop or Docker Engine</td><td>Needed for Docker-backed smoke tests and local clusters.</td></tr><tr><td>Docker Compose</td><td>v2 plugin or v1 standalone</td><td>The Gradle task detects <code>docker compose</code> first, then <code>docker-compose</code>.</td></tr><tr><td>Gradle</td><td>Wrapper only</td><td>Use <code>./gradlew</code>; do not rely on a global Gradle install.</td></tr></tbody></table></div><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>The root build requires an OpenSearch version.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/atlassian-labs/opensearch-aosc.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opensearch-aosc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assemble</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PopensearchVersion=3.6.0</span></span></code></pre></div><p>The plugin ZIP is written under the selected line&#39;s <code>build/distributions/</code> (Gradle prints the exact path).</p><h3 id="gradle-version-per-opensearch-version" tabindex="-1">Gradle version per OpenSearch version <a class="header-anchor" href="#gradle-version-per-opensearch-version" aria-label="Permalink to &quot;Gradle version per OpenSearch version&quot;">​</a></h3><p>OpenSearch 2.15–3.6 build on the committed wrapper (Gradle 8.7). <strong>OpenSearch 3.7 requires Gradle 9.4.1</strong> — its build-tools rejects older Gradle, and the 2.x build-tools breaks on Gradle 9, so no single wrapper serves both lines. Before working on 3.7:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/set-gradle.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.7.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # points the wrapper at Gradle 9.4.1 (drives ./gradlew and the IDE)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/set-gradle.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # restore the default (8.7) when you switch back</span></span></code></pre></div><p>CI runs this per job automatically. Don&#39;t commit the flipped wrapper.</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENSEARCH_INITIAL_ADMIN_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Admin@123</span></span></code></pre></div><p>Supply the OpenSearch version per command, or set a default once in <code>~/.gradle/gradle.properties</code> (<code>opensearchVersion=3.6.0</code>) so a bare <code>./gradlew</code> and IntelliJ import resolve it. The version selects the OpenSearch line (os2/os3):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fastCheck</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PopensearchVersion=3.6.0</span></span></code></pre></div><h2 id="intellij-idea" tabindex="-1">IntelliJ IDEA <a class="header-anchor" href="#intellij-idea" aria-label="Permalink to &quot;IntelliJ IDEA&quot;">​</a></h2><ol><li>Open the repository root.</li><li>Set the Gradle JVM to JDK 21 for the <code>os3</code> line or JDK 17 for the <code>os2</code> line (os2 emits Java 11 bytecode but the build needs JDK 17). Only one line imports per <code>opensearchVersion</code>, so switch the Gradle JVM when you switch lines. For 3.7 work, run <code>./scripts/set-gradle.sh 3.7.0</code> first (IntelliJ reads the wrapper&#39;s Gradle 9.4.1) and re-sync.</li><li>Enable annotation processing for Lombok.</li><li>Import the formatter profile from <code>gradle/formatterConfig.xml</code> if you want IDE formatting to match Spotless.</li><li>Set <code>opensearchVersion</code> in <code>~/.gradle/gradle.properties</code> (e.g. <code>3.6.0</code>) so import resolves the line; override per run configuration with <code>-PopensearchVersion</code>.</li></ol><h2 id="local-docker-cluster" tabindex="-1">Local Docker Cluster <a class="header-anchor" href="#local-docker-cluster" aria-label="Permalink to &quot;Local Docker Cluster&quot;">​</a></h2><p>From the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENSEARCH_INITIAL_ADMIN_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Admin@123</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dockerUp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PopensearchVersion=3.6.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:9200/_cluster/health</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dockerDown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PopensearchVersion=3.6.0</span></span></code></pre></div><p>The compose files live in the selected line&#39;s <code>opensearch-docker/</code> directory. Prefer the Gradle tasks above because they build the plugin ZIP, copy it into the Docker context, select Compose v1 or v2, wait for health, and remove volumes on shutdown.</p><p>If you debug Compose directly, first run <code>./gradlew dockerCopyPlugin -PopensearchVersion=3.6.0</code>, then run Compose from <code>aosc-plugin-os&lt;N&gt;/opensearch-docker/</code> with <code>OPENSEARCH_VERSION</code> (the container image tag) and <code>OPENSEARCH_INITIAL_ADMIN_PASSWORD</code> set.</p><h2 id="common-setup-issues" tabindex="-1">Common Setup Issues <a class="header-anchor" href="#common-setup-issues" aria-label="Permalink to &quot;Common Setup Issues&quot;">​</a></h2><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Problem</th><th>Fix</th></tr></thead><tbody><tr><td><code>opensearchVersion is required</code></td><td>Pass <code>-PopensearchVersion=&lt;version&gt;</code> or set it in <code>~/.gradle/gradle.properties</code>.</td></tr><tr><td><code>java: command not found</code></td><td>Install a JDK and make it available on <code>PATH</code>.</td></tr><tr><td>Docker connection errors</td><td>Start Docker Desktop or Docker Engine.</td></tr><tr><td>Spotless violations</td><td>Run <code>./gradlew spotlessApply -PopensearchVersion=3.6.0</code>.</td></tr><tr><td>Lombok symbols missing in IDE</td><td>Enable annotation processing and reload Gradle.</td></tr></tbody></table></div><h2 id="repository-layout" tabindex="-1">Repository Layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository Layout&quot;">​</a></h2><p>There is one source tree per OpenSearch line, <code>aosc-plugin-os2/</code> and <code>aosc-plugin-os3/</code>, with identical internal structure. Only the line matching <code>-PopensearchVersion</code> participates in a build.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opensearch-aosc/</span></span>
<span class="line"><span>|-- aosc-plugin-os2/            # OpenSearch 2.x source tree (structure below)</span></span>
<span class="line"><span>|-- aosc-plugin-os3/            # OpenSearch 3.x source tree</span></span>
<span class="line"><span>|   |-- src/main/java/          # Plugin source</span></span>
<span class="line"><span>|   |-- src/test/               # Unit tests</span></span>
<span class="line"><span>|   |-- src/itTest/             # In-JVM integration tests</span></span>
<span class="line"><span>|   |-- src/smokeTest/          # REST smoke tests</span></span>
<span class="line"><span>|   |-- src/scaleTest/          # Scale validation tests</span></span>
<span class="line"><span>|   |-- src/benchmarkTest/      # Benchmark tests</span></span>
<span class="line"><span>|   |-- src/yamlRestTest/       # YAML REST tests</span></span>
<span class="line"><span>|   \`-- opensearch-docker/      # Local Docker cluster</span></span>
<span class="line"><span>|-- docs/                       # VitePress documentation</span></span>
<span class="line"><span>|-- gradle/                     # Wrapper, formatter config, shared aosc-plugin.gradle</span></span>
<span class="line"><span>|-- release/                    # Per-line build manifests</span></span>
<span class="line"><span>\`-- scripts/                    # Public helper scripts</span></span></code></pre></div>`,29)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
